package app.loveu;
import android.content.Context;import android.graphics.*;import android.view.*;import java.time.*;import java.util.*;
final class CalendarView extends View {
 interface Selected{void date(String value);}
 final TapGesture tap;final YearMonth month;final Map<String,Integer> counts;final String selected;final Selected listener;final Paint p=new Paint(3);final float density;
 CalendarView(Context c,YearMonth month,Map<String,Integer> counts,String selected,Selected listener){super(c);tap=new TapGesture(ViewConfiguration.get(c).getScaledTouchSlop());this.month=month;this.counts=counts;this.selected=selected;this.listener=listener;density=getResources().getDisplayMetrics().density;setContentDescription(month+"日历；点击日期查看每次时间和次数");setFocusable(true);}
 protected void onDraw(Canvas c){super.onDraw(c);float unit=getWidth()/7f,top=32*density,row=47*density;int offset=month.atDay(1).getDayOfWeek().getValue()-1;p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(11*density);p.setColor(Ui.MUTED);String[] labels={"一","二","三","四","五","六","日"};for(int i=0;i<7;i++)c.drawText(Language.ui(labels[i]),unit*(i+.5f),17*density,p);
  for(int day=1;day<=month.lengthOfMonth();day++){int index=offset+day-1;float x=unit*(index%7+.5f),y=top+row*(index/7+.5f);String date=month.atDay(day).toString();int n=counts.getOrDefault(date,0);boolean chosen=date.equals(selected),today=date.equals(LocalDate.now().toString());if(chosen){p.setColor(chosen?Ui.BERRY:Ui.PINK);c.drawCircle(x,y-5*density,17*density,p);}else if(n>0){p.setColor(Ui.PINK);c.drawCircle(x,y-5*density,17*density,p);}else if(today){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(density);p.setColor(Ui.BERRY);c.drawCircle(x,y-5*density,17*density,p);p.setStyle(Paint.Style.FILL);}p.setColor(chosen?Ui.ON_ACCENT:month.atDay(day).isAfter(LocalDate.now())?Ui.MUTED:Ui.INK);p.setTextSize(13*density);c.drawText(Language.ui(String.valueOf(day)),x,y,p);if(n>0&&!month.atDay(day).isAfter(LocalDate.now())){String count=String.valueOf(n);p.setTextSize(9*density);p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));float badgeWidth=Math.max(16*density,p.measureText(count)+8*density),bx=x+10*density,by=y+7*density;p.setColor(Ui.BERRY);c.drawRoundRect(bx-badgeWidth/2,by-7*density,bx+badgeWidth/2,by+7*density,7*density,7*density,p);p.setColor(Ui.ON_ACCENT);c.drawText(Language.ui(count),bx,by+3*density,p);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));}}
 }
 public boolean onTouchEvent(MotionEvent e){int action=e.getActionMasked();if(e.getPointerCount()>1){tap.cancel();return true;}if(action==MotionEvent.ACTION_DOWN)tap.start(e.getX(),e.getY());else if(action==MotionEvent.ACTION_MOVE)tap.move(e.getX(),e.getY());else if(action==MotionEvent.ACTION_CANCEL)tap.cancel();else if(action==MotionEvent.ACTION_UP){if(!tap.finish(e.getX(),e.getY())||e.getX()<0||e.getX()>=getWidth()||e.getY()<0||e.getY()>=getHeight())return true;int col=Math.min(6,Math.max(0,(int)(e.getX()/(getWidth()/7f)))),row=(int)((e.getY()-32*density)/(47*density));if(e.getY()<32*density)return true;int day=row*7+col-(month.atDay(1).getDayOfWeek().getValue()-1)+1;if(day>=1&&day<=month.lengthOfMonth()){performClick();listener.date(month.atDay(day).toString());}return true;}return true;}
 public boolean performClick(){super.performClick();return true;}
 static int height(YearMonth m){return 32+47*((m.atDay(1).getDayOfWeek().getValue()-1+m.lengthOfMonth()+6)/7)+8;}
}
